import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.C4zpkcTP.js";const i=JSON.parse('{"title":"PaymentCallback & Status","description":"Property reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus enum.","frontmatter":{"title":"PaymentCallback & Status","description":"Property reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus enum."},"headers":[],"relativePath":"php-myanmar-payments/references/payment-callback.md","filePath":"php-myanmar-payments/references/payment-callback.md"}'),c={name:"php-myanmar-payments/references/payment-callback.md"};function r(s,t,n,l,u,y){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="paymentcallback-status" tabindex="-1">PaymentCallback &amp; Status <a class="header-anchor" href="#paymentcallback-status" aria-label="Permalink to &quot;PaymentCallback &amp; Status&quot;">​</a></h1><h2 id="paymentcallback" tabindex="-1">PaymentCallback <a class="header-anchor" href="#paymentcallback" aria-label="Permalink to &quot;PaymentCallback&quot;">​</a></h2><p>Returned by every gateway&#39;s <code>handleCallback()</code> (and AYA&#39;s <code>verifyRedirect()</code>) once the signature is verified. A final class with read-only properties.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The status mapped onto this package&#39;s statuses</td></tr><tr><td><code>gatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value, unmapped</td></tr><tr><td><code>gatewayReference</code></td><td><code>?string</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>amount</code></td><td><code>?string</code></td><td>The amount the gateway reports, exactly as it sent it</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The verified payload, with JSON numbers kept as strings, never <code>float</code></td></tr><tr><td><code>acknowledgement</code></td><td><code>Acknowledgement</code></td><td>The response the gateway expects</td></tr><tr><td><code>isSuccessful()</code></td><td><code>bool</code></td><td><code>status === PaymentStatus::Successful</code></td></tr></tbody></table><p>Build one yourself to test your own fulfillment code, with named arguments: <code>new PaymentCallback(orderId: ..., status: ..., gatewayStatus: ..., gatewayReference: null, amount: null, raw: [], acknowledgement: Acknowledgement::default())</code>. <code>status</code> takes a <code>PaymentStatus</code>, and <code>acknowledgement</code> defaults to <code>Acknowledgement::default()</code>.</p><h2 id="acknowledgement" tabindex="-1">Acknowledgement <a class="header-anchor" href="#acknowledgement" aria-label="Permalink to &quot;Acknowledgement&quot;">​</a></h2><p>A final class in <code>Laranex\\PhpMyanmarPayments\\Http</code> with read-only properties; <code>new Acknowledgement(status: ..., body: ..., headers: ...)</code> builds one, each argument optional.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>int</code></td><td>HTTP status, <code>200</code> by default</td></tr><tr><td><code>body</code></td><td><code>string</code></td><td>Response body, e.g. KBZ Pay&#39;s <code>success</code>; empty by default</td></tr><tr><td><code>headers</code></td><td><code>array&lt;string, string&gt;</code></td><td>Response headers, <code>[&#39;Content-Type&#39; =&gt; &#39;text/plain&#39;]</code> by default</td></tr><tr><td><code>send()</code></td><td><code>void</code></td><td>Writes the status, headers and body with <code>http_response_code()</code>, <code>header()</code> and <code>echo</code></td></tr></tbody></table><p><code>Acknowledgement::default()</code> is an empty <code>200</code> with <code>Content-Type: text/plain</code>. Write it with your framework&#39;s response class, see <a href="/php-myanmar-payments/callbacks.html#acknowledging">Acknowledging</a>.</p><h2 id="paymentstatusresult" tabindex="-1">PaymentStatusResult <a class="header-anchor" href="#paymentstatusresult" aria-label="Permalink to &quot;PaymentStatusResult&quot;">​</a></h2><p>Returned by <code>$kbz-&gt;status()</code>, <code>$aya-&gt;status()</code> and <code>$yoma-&gt;status()</code>. A final class with read-only properties.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>?string</code></td><td>Your order ID; <code>null</code> for Yoma, which returns only the reference</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The mapped status</td></tr><tr><td><code>gatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value</td></tr><tr><td><code>gatewayReference</code></td><td><code>?string</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>amount</code></td><td><code>?string</code></td><td>The amount the gateway reports</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response</td></tr><tr><td><code>isSuccessful()</code></td><td><code>bool</code></td><td><code>status === PaymentStatus::Successful</code></td></tr></tbody></table><h2 id="callbackrequest" tabindex="-1">CallbackRequest <a class="header-anchor" href="#callbackrequest" aria-label="Permalink to &quot;CallbackRequest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>new CallbackRequest(body: &#39;&#39;, headers: [], query: [])</code></td><td><code>CallbackRequest</code></td><td>From the raw parts: the body as a <code>string</code>, the headers as name =&gt; value, the query parameters as an array</td></tr><tr><td><code>CallbackRequest::fromGlobals()</code></td><td><code>CallbackRequest</code></td><td>From <code>php://input</code>, the request headers in <code>$_SERVER</code> and <code>$_GET</code></td></tr><tr><td><code>CallbackRequest::fromPsr7($request)</code></td><td><code>CallbackRequest</code></td><td>From a PSR-7 <code>ServerRequestInterface</code>; repeated headers joined with <code>, </code></td></tr><tr><td><code>CallbackRequest::fromArray($payload, $headers = [])</code></td><td><code>CallbackRequest</code></td><td>From a decoded payload, encoded as a JSON body with <code>Content-Type: application/json</code></td></tr><tr><td><code>body</code></td><td><code>string</code></td><td>The raw body, exactly as received</td></tr><tr><td><code>headers()</code></td><td><code>array&lt;string, string&gt;</code></td><td>Headers as given</td></tr><tr><td><code>query</code></td><td><code>array</code></td><td>Query string parameters</td></tr><tr><td><code>header($name)</code></td><td><code>?string</code></td><td>One header, case-insensitively</td></tr><tr><td><code>parsedBody()</code></td><td><code>array</code></td><td>The body decoded as JSON (when it is a JSON object) or a form (the first value of a repeated key); JSON numbers keep their exact text as strings</td></tr><tr><td><code>input()</code></td><td><code>array</code></td><td>The body merged over the query string</td></tr><tr><td><code>queryInput()</code></td><td><code>array</code></td><td>The query string merged over the body</td></tr></tbody></table><h2 id="paymentstatus" tabindex="-1">PaymentStatus <a class="header-anchor" href="#paymentstatus" aria-label="Permalink to &quot;PaymentStatus&quot;">​</a></h2><p><code>enum PaymentStatus: string</code> in <code>Laranex\\PhpMyanmarPayments\\Enums</code>: <code>$status-&gt;value</code> is the value and <code>PaymentStatus::from($value)</code> reads it back.</p><table tabindex="0"><thead><tr><th>Case</th><th>Value</th></tr></thead><tbody><tr><td><code>PaymentStatus::Successful</code></td><td><code>successful</code></td></tr><tr><td><code>PaymentStatus::Pending</code></td><td><code>pending</code></td></tr><tr><td><code>PaymentStatus::Failed</code></td><td><code>failed</code></td></tr><tr><td><code>PaymentStatus::Canceled</code></td><td><code>canceled</code></td></tr><tr><td><code>PaymentStatus::Expired</code></td><td><code>expired</code></td></tr><tr><td><code>PaymentStatus::Unknown</code></td><td><code>unknown</code></td></tr></tbody></table><p><code>PaymentStatus::cases()</code> lists every status. <code>$status-&gt;isFinal()</code> is <code>false</code> for <code>Pending</code> and <code>Unknown</code>. <code>PaymentStatus::resolve($statuses, $gatewayStatus)</code> maps a trimmed gateway value through an array and returns <code>PaymentStatus::Unknown</code> when it is not listed.</p>',18)])])}const m=e(c,[["render",r]]);export{i as __pageData,m as default};
